CREATE proc usp_Nameproduction 
AS
BEGIN

CREATE TABLE #T1(ID INT IDENTITY(1,1) NOT NULL PRIMARY KEY(ID), CODEPRODUTION NVARCHAR(100) NULL,PRODUCTIONNAME NVARCHAR(150) NULL,UNIT NVARCHAR(10) NULL, IsUsed BIT NULL)

--Thành phẩm   VEB3R0107QG(2245)
--Thành phẩm   VEC2R7506QG(1840)
--Thành phẩm   VEC3R0367QG (3562)
--Thành phẩm   WEC3R0186QC (1325) TAPING
--Thành phẩm   WEC3R0256QG-B11R (1625)
--TP  VEC6R0505QG-I (1030)
--TP WEC6R0126QG-H (1625)

--SELECT PRODUCTIONNAME, COUNT(*)
--FROM #T1 
--GROUP BY PRODUCTIONNAME
--HAVING COUNT(*) > 1

SELECT 
		DISTINCT
		CODEPRODUTION,
		PRODUCTIONNAME,
		UNIT
FROM
		#T1
WHERE
		IsUsed = 1

		DROP TABLE #T1
END